//! Experimental native pipeline segments. Never cache an owner across callbacks.
use crate::{cpu::CpuContext,mem::{Mem,ConstPtr,MutPtr}};
#[derive(Copy,Clone,Default,Debug)]pub(crate)struct Write{pub a:u32,pub n:u8,pub value:u32}
#[derive(Copy,Clone,Default,Debug)]pub(crate)struct Touch{pub a:u32,pub n:u8,pub before:u32}
#[derive(Default)]struct Pages{values:[u32;8],n:usize}
impl Pages{fn check(&mut self,mem:&Mem,a:u32,n:u32)->bool{if n==0||n>4||a.checked_add(n).is_none()||a<mem.null_segment_size(){return false;}let page=a&!4095;if a+ n-1 &!4095==page{if self.values[..self.n].contains(&page){return true;}if mem.is_mapped_range(page,4096){if self.n<8{self.values[self.n]=page;self.n+=1;}return true;}}mem.is_mapped_range(a,n)}}
pub(crate)trait Access{fn read(&mut self,a:u32,n:u32)->Option<u32>;fn write(&mut self,a:u32,n:u32,value:u32)->Option<()>;}
pub(crate)struct Predict<'a>{mem:&'a Mem,pages:Pages,pub writes:[Write;32],pub nw:usize,pub touches:[Touch;64],pub nt:usize}
impl<'a> Predict<'a>{pub fn new(mem:&'a Mem)->Self{Self{mem,pages:Pages::default(),writes:[Write::default();32],nw:0,touches:[Touch::default();64],nt:0}}fn raw(&mut self,a:u32,n:u32)->Option<u32>{if !self.pages.check(self.mem,a,n){return None;}let b=self.mem.get_bytes_fallible(ConstPtr::<u8>::from_bits(a).cast(),n)?;let mut v=[0;4];v[..n as usize].copy_from_slice(b);Some(u32::from_le_bytes(v))}fn touch(&mut self,a:u32,n:u32,before:u32)->Option<()>{if self.nt==64{return None;}self.touches[self.nt]=Touch{a,n:n as u8,before};self.nt+=1;Some(())}pub fn expected(&self,a:u32,n:u32,before:u32)->u32{let mut b=before.to_le_bytes();for w in &self.writes[..self.nw]{for i in 0..n{if let Some(j)=(a+i).checked_sub(w.a){if j<u32::from(w.n){b[i as usize]=w.value.to_le_bytes()[j as usize];}}}}u32::from_le_bytes(b)}}

impl Access for Predict<'_>{fn read(&mut self,a:u32,n:u32)->Option<u32>{let before=self.raw(a,n)?;self.touch(a,n,before)?;Some(self.expected(a,n,before))}fn write(&mut self,a:u32,n:u32,value:u32)->Option<()>{let before=self.raw(a,n)?;self.touch(a,n,before)?;if self.nw==32{return None;}self.writes[self.nw]=Write{a,n:n as u8,value};self.nw+=1;Some(())}}
pub(crate)struct Machine<A:Access>{pub c:CpuContext,pub a:A,pub retired:u32}
impl<A:Access> Machine<A>{pub fn nz(&mut self,v:u32){self.c.cpsr=(self.c.cpsr&0x3fffffff)|(v&0x80000000)|if v==0{0x40000000}else{0};}pub fn cmp(&mut self,a:u32,b:u32){self.sub_flags(a,b)}pub fn sub_flags(&mut self,a:u32,b:u32){let v=a.wrapping_sub(b);self.c.cpsr=(self.c.cpsr&0x0fffffff)|(v&0x80000000)|if v==0{0x40000000}else{0}|if a>=b{0x20000000}else{0}|if((a^b)&(a^v))>>31!=0{0x10000000}else{0};}pub fn add_flags(&mut self,a:u32,b:u32){let(v,carry)=a.overflowing_add(b);self.c.cpsr=(self.c.cpsr&0x0fffffff)|(v&0x80000000)|if v==0{0x40000000}else{0}|if carry{0x20000000}else{0}|if(!(a^b)&(a^v))>>31!=0{0x10000000}else{0};}pub fn cond(&self,s:&str)->bool{let(n,z,c,v)=(self.c.cpsr>>31,self.c.cpsr>>30&1,self.c.cpsr>>29&1,self.c.cpsr>>28&1);match s{"eq"=>z==1,"ne"=>z==0,"hs"=>c==1,"lo"=>c==0,"mi"=>n==1,"pl"=>n==0,"vs"=>v==1,"vc"=>v==0,"hi"=>c==1&&z==0,"ls"=>c==0||z==1,"ge"=>n==v,"lt"=>n!=v,"gt"=>z==0&&n==v,"le"=>z==1||n!=v,_=>false}}pub fn shift(&mut self,a:u32,n:u32,kind:u8,flags:bool)->u32{let n=n&255;let(v,c)=if n==0{(a,self.c.cpsr>>29&1)}else{match kind{0=>if n>32{(0,0)}else if n==32{(0,a&1)}else{(a<<n,a>>(32-n)&1)},1=>if n>32{(0,0)}else if n==32{(0,a>>31)}else{(a>>n,a>>(n-1)&1)},2=>if n>=32{(((a as i32)>>31)as u32,a>>31)}else{(((a as i32)>>n)as u32,a>>(n-1)&1)},3=>{let v=a.rotate_right(n&31);(v,v>>31)},_=>return a}};if flags{self.nz(v);self.c.cpsr=(self.c.cpsr&!0x20000000)|(c<<29);}v}}
pub(crate)struct Outcome{pub context:CpuContext,pub retired:u32,pub writes:[Write;32],pub nw:usize,pub touches:[Touch;64],pub nt:usize}
impl Outcome{pub fn compare_memory(&self,mem:&Mem)->bool{self.touches[..self.nt].iter().all(|t|{let mut expected=t.before.to_le_bytes();for w in &self.writes[..self.nw]{for i in 0..t.n{if let Some(j)=(t.a+u32::from(i)).checked_sub(w.a){if j<u32::from(w.n){expected[i as usize]=w.value.to_le_bytes()[j as usize];}}}}mem.bytes_at(ConstPtr::<u8>::from_bits(t.a),u32::from(t.n))==&expected[..t.n as usize]})}pub fn commit(&self,mem:&mut Mem){for w in &self.writes[..self.nw]{mem.bytes_at_mut(MutPtr::<u8>::from_bits(w.a),u32::from(w.n)).copy_from_slice(&w.value.to_le_bytes()[..w.n as usize]);}}}
pub(crate)fn predict(mem:&Mem,c:CpuContext,index:usize)->Option<Outcome>{if c.cpsr&0x20==0||c.cpsr&0x0600fc00!=0{return None;}let mut m=Machine{c,a:Predict::new(mem),retired:0};crate::pipeline_generated::execute(index,&mut m)?;let block=crate::pipeline_generated::BLOCKS[index];if m.a.writes[..m.a.nw].iter().any(|w|u64::from(w.a)<u64::from(block.4)&&u64::from(block.0)<u64::from(w.a)+u64::from(w.n)){return None;}Some(Outcome{context:m.c,retired:m.retired,writes:m.a.writes,nw:m.a.nw,touches:m.a.touches,nt:m.a.nt})}
#[derive(Default,Clone)]pub(crate)struct Gate{pub total:u64,pub classes:[u64;2],pub calls:u64,pub fast:u64,pub disabled:bool}
#[derive(Default)]pub(crate)struct State{pub font_bucket:crate::font_bucket::State,pub enabled:bool,pub active_groups:[bool;3],pub functions:Vec<bool>,pub gates:Vec<Gate>,pub group_shadows:[u64;3],pub group_fast:[u64;3],#[cfg(test)]pub fault:Option<usize>}
impl State{
 pub fn configure(&mut self,verified:bool,mem:&Mem,bins:&[crate::mach_o::MachO],flags:[bool;3]){use digest::Digest;let fs=crate::pipeline_generated::FUNCTIONS;self.functions=vec![false;fs.len()];self.gates=vec![Gate::default();crate::pipeline_generated::BLOCKS.len()];for(i,&(name,a,n,hash,group))in fs.iter().enumerate(){if !verified||!flags[group as usize]{continue;}let symbol=bins.first().and_then(|b|b.exported_symbols.get(name));let symbol_ok=symbol.is_some_and(|x|*x==(a|1))||!name.starts_with("__Z")&&symbol.is_none();let valid=symbol_ok&&mem.is_mapped_range(a,n)&&format!("{:x}",sha1::Sha1::digest(mem.bytes_at(ConstPtr::<u8>::from_bits(a),n)))==hash;self.functions[i]=valid;event(group as usize,i,a,if valid{"function_guard_passed"}else{"function_guard_rejected"},0);}self.enabled=self.functions.iter().any(|x|*x);self.font_bucket.enabled=self.functions.first()==Some(&true)&&std::env::var("PEGGLE_FONT_BUCKET_SCAN").as_deref()!=Ok("0");crate::diagnostics::event(&format!("{{\"event\":\"font_bucket_policy\",\"enabled\":{}}}",self.font_bucket.enabled));self.active_groups=[false;3];for(i,ok)in self.functions.iter().enumerate(){if *ok{self.active_groups[crate::pipeline_generated::FUNCTIONS[i].4 as usize]=true;}}}
 pub fn eligible(&self,index:usize)->bool{let b=crate::pipeline_generated::BLOCKS[index];self.enabled&&self.functions[b.3 as usize]&&!self.gates[index].disabled}
 pub fn shadow(&self,index:usize,_class:usize)->bool{let b=crate::pipeline_generated::BLOCKS[index];let g=&self.gates[index];g.total<32||self.group_shadows[b.2 as usize]<128||(g.calls+1)%1024==0}
 pub fn checked(&mut self,index:usize,class:usize,ok:bool){let b=crate::pipeline_generated::BLOCKS[index];let g=&mut self.gates[index];g.calls+=1;if !ok{g.disabled=true;event(b.2 as usize,b.3 as usize,b.0,"block_disabled_after_mismatch",g.calls);return;}g.total+=1;g.classes[class]+=1;self.group_shadows[b.2 as usize]+=1;if g.total==32{event(b.2 as usize,b.3 as usize,b.0,"block_real32_passed",32);}if g.classes[class]==16{event(b.2 as usize,b.3 as usize,b.0,if class==0{"observed_exit0_16"}else{"observed_exit1_16"},16);}if self.group_shadows[b.2 as usize]==128{event(b.2 as usize,b.3 as usize,b.0,"group_real128_passed",128);}}
 pub fn accelerated(&mut self,index:usize){let b=crate::pipeline_generated::BLOCKS[index];let g=&mut self.gates[index];g.calls+=1;g.fast+=1;self.group_fast[b.2 as usize]+=1;if g.fast==1{event(b.2 as usize,b.3 as usize,b.0,"block_fast_calls",1);}let n=self.group_fast[b.2 as usize];if n%65536==0{event(b.2 as usize,b.3 as usize,b.0,"group_fast_calls",n);}}
}
fn event(group:usize,function:usize,pc:u32,kind:&str,count:u64){crate::diagnostics::event(&format!("{{\"event\":\"experimental_pipeline_native\",\"group\":{group},\"function\":{function},\"pc\":{pc},\"kind\":\"{kind}\",\"count\":{count}}}"));}

pub(crate)fn code_matches(mem:&Mem,index:usize)->bool{let b=crate::pipeline_generated::BLOCKS[index];let raw=crate::pipeline_generated::RAW_BLOCKS[index];mem.get_bytes_fallible(ConstPtr::<u8>::from_bits(b.0).cast(),raw.len()as u32).is_some_and(|bytes|bytes==raw)}
#[cfg(test)]impl State{pub fn arm_fixture(&mut self,flags:[bool;3]){self.functions=crate::pipeline_generated::FUNCTIONS.iter().map(|f|flags[f.4 as usize]).collect();self.gates=vec![Gate::default();crate::pipeline_generated::BLOCKS.len()];self.enabled=flags.iter().any(|x|*x);self.active_groups=flags;}pub fn stats(&self)->([u64;3],[u64;3],usize){(self.group_shadows,self.group_fast,self.gates.iter().filter(|g|g.disabled).count())}}

impl State{#[inline(always)]pub fn maybe_pc(&self,pc:u32)->bool{self.active_groups[0]&&pc.wrapping_sub(0x245bf8)<0xcb8||self.active_groups[1]&&(pc.wrapping_sub(0x287ddc)<820||pc.wrapping_sub(0x2a7814)<0xa6c)||self.active_groups[2]&&pc.wrapping_sub(0x6019c)<0xdac}}

/// Fast memory follows the existing interpreter's fallible scalar-memory checks.
/// No callbacks or persistent owner/cache survive this segment. Each instruction
/// has at most one memory operation, allowing exact partial-progress resumption.
pub(crate)struct Live<'a>{mem:&'a mut Mem,lo:u32,hi:u32}
impl Access for Live<'_>{#[inline(always)]fn read(&mut self,a:u32,n:u32)->Option<u32>{if n==0||n>4||a<self.mem.null_segment_size(){return None;}let b=self.mem.get_bytes_fallible(ConstPtr::<u8>::from_bits(a).cast(),n)?;let mut v=[0;4];v[..n as usize].copy_from_slice(b);Some(u32::from_le_bytes(v))}#[inline(always)]fn write(&mut self,a:u32,n:u32,v:u32)->Option<()>{if n==0||n>4||a<self.mem.null_segment_size()||u64::from(a)<u64::from(self.hi)&&u64::from(self.lo)<u64::from(a)+u64::from(n){return None;}self.mem.get_bytes_fallible_mut(ConstPtr::<u8>::from_bits(a).cast(),n)?.copy_from_slice(&v.to_le_bytes()[..n as usize]);Some(())}}
pub(crate)struct Fast{pub regs:[u32;16],pub cpsr:u32,pub retired:u32,pub complete:bool}
pub(crate)fn fast(mem:&mut Mem,regs:[u32;16],cpsr:u32,index:usize)->Fast{let b=crate::pipeline_generated::BLOCKS[index];let mut m=Machine{c:CpuContext{regs,extregs:[0;64],cpsr,fpscr:0},a:Live{mem,lo:b.0,hi:b.4},retired:0};let complete=crate::pipeline_generated::execute(index,&mut m).is_some();Fast{regs:m.c.regs,cpsr:m.c.cpsr,retired:m.retired,complete}}
